class Vector:
    def __init__(self, x):
        self.x = x

    def __add__(self, other):
        if isinstance(other, (int, float)):
            return Vector(self.x + other)
        if isinstance(other, Vector):
            return Vector(self.x + other.x)
        return NotImplemented

    __radd__ = __add__

    def __repr__(self):
        return f"Vector({self.x})"


print(Vector(1) + Vector(2))
print(Vector(1) + 10)
print(10 + Vector(1))

class Accumulator:
    def __init__(self):
        self.total = 0

    def __iadd__(self, other):
        self.total += other
        return self


acc = Accumulator()
acc += 5
acc += 3
print(acc.total)

class Quantity:
    def __init__(self, n):
        self.n = n

    def __index__(self):
        return self.n


q = Quantity(1)
print([10, 20, 30][q])
print(["a", "b", "c"][q:])
